//! Shared harness: drives a `Broker` one line at a time and checks replies.

use miniq::Broker;
use serde_json::{Value, json};

#[derive(Default)]
pub struct Session(Broker);

impl Session {
    /// Runs a raw line (without its newline) and returns the reply as JSON.
    pub fn line(&mut self, line: &[u8]) -> Value {
        serde_json::to_value(self.0.handle_line(line)).expect("a Response always serializes")
    }

    pub fn run(&mut self, command: Value) -> Value {
        self.line(command.to_string().as_bytes())
    }

    /// Runs `command` and asserts it fails with exactly `code`, a string
    /// message and no other top-level members.
    #[track_caller]
    pub fn fails(&mut self, command: Value, code: &str) {
        assert_error(&self.run(command), code);
    }
}

#[track_caller]
pub fn assert_error(reply: &Value, code: &str) {
    let message = &reply["error"]["message"];
    assert!(message.is_string(), "no string message in {reply}");
    assert_eq!(
        *reply,
        json!({"ok": false, "error": {"code": code, "message": message}})
    );
}
EOF
cat > tests/protocol.rs <<'EOF'
mod support;

use serde_json::json;
use support::{Session, assert_error};

#[test]
fn malformed_requests_are_invalid_and_the_session_continues() {
    let lines: &[&[u8]] = &[
        b"",
        b"   ",
        b"not json",
        b"[1, 2]",
        b"\"Tick\"",
        b"{\"Command\": \"Tick\", \"Seconds\": 1} trailing",
        b"{\"Command\": \"Tick\", \"Seconds\": 1}{}",
        b"{}",
        b"{\"Command\": 7}",
        b"{\"Command\": null}",
        b"{\"Command\": \"tick\"}",
        b"{\"Command\": \"Nope\"}",
        b"{\"Command\": \"Tick\", \"Seconds\": \"\xff\"}",
    ];
    let mut session = Session::default();
    for line in lines {
        assert_error(&session.line(line), "InvalidRequest");
    }
    assert_eq!(
        session.run(json!({"Command": "Tick", "Seconds": 1})),
        json!({"ok": true, "Now": 1})
    );
}

#[test]
fn tick_advances_the_clock_and_reports_it() {
    let mut session = Session::default();
    assert_eq!(
        session.run(json!({"Command": "Tick", "Seconds": 0})),
        json!({"ok": true, "Now": 0})
    );
    assert_eq!(
        session.run(json!({"Command": "Tick", "Seconds": 1209600, "Extra": [1]})),
        json!({"ok": true, "Now": 1209600})
    );
    assert_eq!(
        session.line(br#"{"Command":"Tick","Seconds":5}"#),
        json!({"ok": true, "Now": 1209605})
    );
}

#[test]
fn tick_parameter_errors() {
    let mut session = Session::default();
    session.fails(json!({"Command": "Tick"}), "MissingParameter");
    session.fails(json!({"Command": "Tick", "Seconds": null}), "MissingParameter");
    session.fails(json!({"Command": "Tick", "Seconds": 1209601}), "InvalidParameterValue");
    session.fails(json!({"Command": "Tick", "Seconds": "5"}), "InvalidParameterValue");
    assert_eq!(
        session.run(json!({"Command": "Tick", "Seconds": 0})),
        json!({"ok": true, "Now": 0})
    );
}
EOF
