/// A message's place in its queue's arrival order; never reused within a queue.
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Hash)]
struct Arrival(u64);

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum MessageState {
