    assert_eq!(session.run(send("other", Some("x"))), json!({"ok": true, "MessageId": "m-2", "SequenceNumber": 2}));
    assert_eq!(session.run(send("x", None)), json!({"ok": true, "MessageId": "m-2", "SequenceNumber": 2}));
