    session.tick(1);
    assert_eq!(session.receive("q"), json!({"ok": true, "Messages": []}));
    assert_eq!(session.counts("q"), counts(0, 0, 0));
    assert_eq!(session.counts("dlq"), counts(2, 0, 0));
